<script lang="ts">
  // Generated by design-engine /design-settings-page
  // Adapter: sveltekit
  // Dev-only — gate with `if (!import.meta.env.DEV) error(404);` in +page.ts
  //
  // Note: This is a dev-only token viewer. Edits produce a copyable CSS snippet —
  //       paste it into your theme.css to apply. Live write-back is a v0.x feature.

  import { browser } from '$app/environment';

  type TokenSet = {
    brand: string;
    primary: string;
    background: string;
    card: string;
    foreground: string;
    destructive: string;
    success: string;
    warning: string;
    info: string;
    font: string;
  };

  let tokens = $state<TokenSet>({
    brand: '#721FE5',
    primary: '#030213',
    background: '#FAFAFA',
    card: '#FFFFFF',
    foreground: '#2A2A2A',
    destructive: '#d4183d',
    success: '#6B9B7A',
    warning: '#D97706',
    info: '#3B82F6',
    font: 'Inter',
  });

  let cssOutput = $derived(`:root {
  --brand: ${tokens.brand};
  --primary: ${tokens.primary};
  --background: ${tokens.background};
  --card: ${tokens.card};
  --foreground: ${tokens.foreground};
  --destructive: ${tokens.destructive};
  --success: ${tokens.success};
  --warning: ${tokens.warning};
  --info: ${tokens.info};
  --font-primary: ${tokens.font}, system-ui, sans-serif;
}`);

  function copyCss() {
    if (!browser) return;
    navigator.clipboard.writeText(cssOutput);
    alert('CSS copied — paste into your theme.css :root block.');
  }

  function downloadCss() {
    if (!browser) return;
    const blob = new Blob([cssOutput], { type: 'text/css' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'theme.css';
    a.click();
    URL.revokeObjectURL(url);
  }

  const colorKeys = ['brand', 'primary', 'background', 'card', 'foreground', 'destructive', 'success', 'warning', 'info'] as const;
</script>

