      <button onclick={copyCss} class="px-4 py-2 bg-primary text-white rounded-md">Copy CSS</button>
      <button onclick={downloadCss} class="px-4 py-2 border rounded-md">Download theme.css</button>
    </div>
  </div>
</div>
